fn main() {
    let matches = cli::build_command().get_matches();
    let cfg = match config::Config::from_matches(&matches) {
        Ok(c) => c,
        Err(e) => {
            print_error(&e);
            std::process::exit(1);
        }
    };

    if let Some(shell) = cfg.generate {
        let mut cmd = cli::build_command();
        clap_complete::generate(shell, &mut cmd, "onefetch", &mut std::io::stdout());
        return;
    }

