//! Rough human-readable relative time formatting.

pub fn humanize(seconds_diff: i64) -> String {
    // seconds_diff = now - then (positive => past)
    let past = seconds_diff >= 0;
    let n = seconds_diff.abs();
    let minutes = n / 60;
    let hours = n / 3600;
    let days = n / 86400;
    let weeks = n / 604800;

    enum P {
        Now,
        Seconds(i64),
        Minutes(i64),
        Hours(i64),
        Days(i64),
        Weeks(i64),
        Months(i64),
        Years(i64),
    }

    let p = if n <= 10 {
        P::Now
    } else if n <= 45 {
        P::Seconds(n)
    } else if n <= 90 {
        P::Minutes(1)
    } else if n <= 45 * 60 {
        P::Minutes(minutes.max(2))
    } else if n <= 90 * 60 {
        P::Hours(1)
    } else if n <= 22 * 3600 {
        P::Hours(hours.max(2))
    } else if n <= 36 * 3600 {
        P::Days(1)
    } else if n <= 13 * 43200 {
        // 6.5 days
        P::Days(days.max(2))
    } else if n <= 21 * 43200 {
        // 10.5 days
        P::Weeks(1)
    } else if n <= 29 * 86400 {
        P::Weeks(weeks.max(2))
    } else if n <= 45 * 86400 {
        P::Months(1)
    } else if n <= 345 * 86400 {
        P::Months((days / 30).max(2))
    } else if n <= 547 * 86400 {
        P::Years(1)
    } else {
        P::Years((days / 365).max(2))
    };

    let text = match p {
        P::Now => return "now".to_string(),
        P::Seconds(x) => format!("{} seconds", x),
        P::Minutes(1) => "a minute".to_string(),
        P::Minutes(x) => format!("{} minutes", x),
        P::Hours(1) => "an hour".to_string(),
        P::Hours(x) => format!("{} hours", x),
        P::Days(1) => "a day".to_string(),
        P::Days(x) => format!("{} days", x),
        P::Weeks(1) => "a week".to_string(),
        P::Weeks(x) => format!("{} weeks", x),
        P::Months(1) => "a month".to_string(),
        P::Months(x) => format!("{} months", x),
        P::Years(1) => "a year".to_string(),
        P::Years(x) => format!("{} years", x),
    };
    if past {
        format!("{} ago", text)
    } else {
        format!("in {}", text)
    }
}

/// Format a unix timestamp as ISO 8601 in UTC: YYYY-MM-DDTHH:MM:SSZ
pub fn iso8601_utc(ts: i64) -> String {
    let days = ts.div_euclid(86400);
    let secs = ts.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z",
        y,
        m,
        d,
        secs / 3600,
        (secs % 3600) / 60,
        secs % 60
    )
}

// Howard Hinnant's algorithm
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}
