pub mod url;

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use anyhow::{anyhow, Context, Result};
use git2::{Delta, DiffOptions, Oid, Repository, Sort, StatusOptions, StatusShow};
use regex::Regex;

pub struct Author {
    pub name: String,
    pub email: String,
    pub commits: usize,
}

pub struct CommitMetrics {
    pub authors: Vec<Author>,
    pub total_commits: usize,
    pub first_commit_time: i64,
    pub last_commit_time: i64,
    pub churn: Vec<(String, usize)>,
    pub churn_pool_size: usize,
}

pub struct Repo {
    pub repo: Repository,
    pub workdir: PathBuf,
}

impl Repo {
    pub fn open(input: &Path, input_display: &str) -> Result<Repo> {
        let repo = Repository::discover(input).map_err(|_| {
            anyhow!(
                "Could not find a git repository in '{}' or in any of its parents",
                input_display
            )
        })?;
        let workdir = match repo.workdir() {
            Some(w) => w.to_path_buf(),
            None => {
                return Err(anyhow!(
                    "Could not find a git repository in '{}' or in any of its parents",
                    input_display
                ))
            }
        };
        Ok(Repo { repo, workdir })
    }

    pub fn git_dir(&self) -> PathBuf {
        self.repo.path().to_path_buf()
    }

    /// Name and email of the committer as configured, if both are available.
    pub fn committer_name(&self) -> String {
        let config = self.repo.config().ok();
        let get = |key: &str| -> Option<String> {
            config
                .as_ref()
                .and_then(|c| c.get_string(key).ok())
        };
        let name = std::env::var("GIT_COMMITTER_NAME")
            .ok()
            .or_else(|| get("user.name"));
        let email = std::env::var("GIT_COMMITTER_EMAIL")
            .ok()
            .or_else(|| get("user.email"))
            .or_else(|| std::env::var("EMAIL").ok());
        match (name, email) {
            (Some(n), Some(_)) => n,
            _ => String::new(),
        }
    }

    pub fn head_commit(&self) -> Result<git2::Commit<'_>> {
        let head = self.repo.head().map_err(|e| {
            anyhow!("Failed to traverse Git commit history").context(e.to_string())
        })?;
        head.peel_to_commit()
            .map_err(|e| anyhow!("Failed to traverse Git commit history").context(e.to_string()))
    }

    pub fn is_shallow(&self) -> bool {
        self.repo.is_shallow()
    }

    pub fn head_refs(&self) -> Result<(String, Vec<String>)> {
        let head = match self.repo.head() {
            Ok(h) => h,
            Err(_) => return Err(unborn_error(&self.repo)),
        };
        let commit = head
            .peel_to_commit()
            .map_err(|_| unborn_error(&self.repo))?;
        let short = commit
            .as_object()
            .short_id()
            .ok()
            .and_then(|b| b.as_str().map(|s| s.to_string()))
            .unwrap_or_else(|| commit.id().to_string()[..7].to_string());
        let mut refs = Vec::new();
        if head.is_branch() {
            if let Some(name) = head.shorthand() {
                refs.push(name.to_string());
                if let Some(tracking) = self.remote_tracking_name(name) {
                    refs.push(tracking);
                }
            }
        }
        Ok((short, refs))
    }

    /// Compute the remote tracking branch name (push semantics, like git's "simple" mode).
    fn remote_tracking_name(&self, branch: &str) -> Option<String> {
        let config = self.repo.config().ok()?;
        let get = |key: &str| -> Option<String> { config.get_string(key).ok() };
        let remote_name = get(&format!("branch.{}.pushRemote", branch))
            .or_else(|| get("remote.pushDefault"))
            .or_else(|| get(&format!("branch.{}.remote", branch)))?;
        let remote = self.repo.find_remote(&remote_name).ok()?;
        // Determine the remote ref we would push to.
        let full_local = format!("refs/heads/{}", branch);
        let push_specs: Vec<String> = remote
            .push_refspecs()
            .ok()
            .map(|s| s.iter().flatten().map(|x| x.to_string()).collect())
            .unwrap_or_default();
        let remote_ref = if !push_specs.is_empty() {
            let mut found = None;
            for spec in &push_specs {
                if let Some(dst) = map_refspec(spec, &full_local) {
                    found = Some(dst);
                    break;
                }
            }
            found?
        } else {
            let merge = get(&format!("branch.{}.merge", branch))?;
            let fetch_remote = get(&format!("branch.{}.remote", branch))?;
            if fetch_remote != remote_name {
                return None;
            }
            if merge != full_local {
                return None;
            }
            merge
        };
        let fetch_specs: Vec<String> = remote
            .fetch_refspecs()
            .ok()
            .map(|s| s.iter().flatten().map(|x| x.to_string()).collect())
            .unwrap_or_default();
        for spec in &fetch_specs {
            if let Some(dst) = map_refspec(spec, &remote_ref) {
                return Some(shorten_ref(&dst));
            }
        }
        None
    }

    pub fn number_of_tags(&self) -> usize {
        self.repo
            .references_glob("refs/tags/*")
            .map(|r| r.count())
            .unwrap_or(0)
    }

    pub fn number_of_branches(&self) -> usize {
        let n = self
            .repo
            .references_glob("refs/remotes/*")
            .map(|r| r.count())
            .unwrap_or(0);
        if n > 0 {
            n - 1
        } else {
            0
        }
    }

    /// Remote URL (push url preferred), with insteadOf rewriting applied.
    pub fn remote_url(&self) -> Result<Option<String>> {
        let config = self.repo.config().ok();
        let has_section = config
            .as_ref()
            .and_then(|c| c.entries(Some("remote.origin.*")).ok())
            .map(|mut entries| {
                let mut any = false;
                while let Some(Ok(_)) = entries.next() {
                    any = true;
                }
                any
            })
            .unwrap_or(false);
        if !has_section {
            return Ok(None);
        }
        let get = |key: &str| -> Option<String> {
            config.as_ref().and_then(|c| c.get_string(key).ok())
        };
        let url = get("remote.origin.url");
        let pushurl = get("remote.origin.pushurl");
        match (url, pushurl) {
            (None, None) => Err(anyhow!("Failed to determine repository URL").context(
                "Neither 'url` nor 'pushUrl' fields were set in the remote's configuration.",
            )),
            (Some(u), None) => Ok(Some(self.rewrite_url(&u, false))),
            (_, Some(p)) => Ok(Some(self.rewrite_url(&p, true))),
        }
    }

    fn rewrite_url(&self, url: &str, push: bool) -> String {
        let config = match self.repo.config() {
            Ok(c) => c,
            Err(_) => return url.to_string(),
        };
        let mut best: Option<(usize, String)> = None;
        let keys: &[&str] = if push {
            &["pushInsteadOf", "insteadOf"]
        } else {
            &["insteadOf"]
        };
        for key in keys {
            if let Ok(mut entries) = config.entries(Some(&format!("url.*.{}", key))) {
                while let Some(Ok(entry)) = entries.next() {
                    let name = match entry.name() {
                        Some(n) => n,
                        None => continue,
                    };
                    let value = match entry.value() {
                        Some(v) => v,
                        None => continue,
                    };
                    // name = url.<base>.insteadOf
                    let base = &name[4..name.len() - key.len() - 1];
                    if url.starts_with(value) {
                        let l = value.len();
                        if best.as_ref().map(|b| l > b.0).unwrap_or(true) {
                            best = Some((l, format!("{}{}", base, &url[l..])));
                        }
                    }
                }
            }
            if best.is_some() {
                break;
            }
        }
        best.map(|b| b.1).unwrap_or_else(|| url.to_string())
    }

    pub fn pending(&self) -> (usize, usize, usize) {
        let mut opts = StatusOptions::new();
        opts.show(StatusShow::Workdir)
            .include_untracked(true)
            .recurse_untracked_dirs(true)
            .include_ignored(false)
            .exclude_submodules(true);
        let (mut added, mut deleted, mut modified) = (0, 0, 0);
        if let Ok(statuses) = self.repo.statuses(Some(&mut opts)) {
            for s in statuses.iter() {
                let st = s.status();
                if st.contains(git2::Status::WT_NEW) {
                    added += 1;
                } else if st.contains(git2::Status::WT_DELETED) {
                    deleted += 1;
                } else if st.contains(git2::Status::WT_MODIFIED)
                    || st.contains(git2::Status::WT_TYPECHANGE)
                    || st.contains(git2::Status::WT_RENAMED)
                {
                    modified += 1;
                }
            }
        }
        (added, deleted, modified)
    }

    /// Repository size and file count based on the index.
    pub fn size(&self) -> (u64, usize) {
        let mut total: u64 = 0;
        let mut count = 0usize;
        if let Ok(index) = self.repo.index() {
            for entry in index.iter() {
                total += entry.file_size as u64;
                count += 1;
            }
        }
        (total, count)
    }

    /// Version from tags: tag whose target commit is most recent; ties broken by name order.
    pub fn version_from_tags(&self) -> Option<String> {
        let mut best: Option<(i64, String)> = None;
        let names = self.repo.tag_names(None).ok()?;
        let mut sorted: Vec<&str> = names.iter().flatten().collect();
        sorted.sort();
        for name in sorted {
            let full = format!("refs/tags/{}", name);
            let r = match self.repo.find_reference(&full) {
                Ok(r) => r,
                Err(_) => continue,
            };
            let commit = match r.peel_to_commit() {
                Ok(c) => c,
                Err(_) => continue,
            };
            let t = commit.time().seconds();
            match &best {
                Some((bt, _)) if *bt >= t => {}
                _ => best = Some((t, name.to_string())),
            }
        }
        best.map(|b| b.1)
    }

    pub fn commit_metrics(
        &self,
        no_merges: bool,
        bot_regex: Option<&Regex>,
        churn_pool_size: Option<usize>,
    ) -> Result<CommitMetrics> {
        let head = self.head_commit()?;
        let mut revwalk = self
            .repo
            .revwalk()
            .context("Failed to traverse Git commit history")?;
        revwalk.set_sorting(Sort::TIME).ok();
        revwalk
            .push(head.id())
            .context("Failed to traverse Git commit history")?;

        let mailmap = self.repo.mailmap().ok();

        let mut authors: HashMap<(String, String), usize> = HashMap::new();
        let mut total_commits = 0usize;
        let mut first_time: Option<i64> = None;
        let mut last_time: Option<i64> = None;
        let mut churn: HashMap<String, usize> = HashMap::new();
        let mut churn_count = 0usize;
        let churn_limit = churn_pool_size.unwrap_or(1);

        for oid in revwalk {
            let oid = match oid {
                Ok(o) => o,
                Err(_) => continue,
            };
            let commit = match self.repo.find_commit(oid) {
                Ok(c) => c,
                Err(_) => continue,
            };
            if no_merges && commit.parent_count() > 1 {
                continue;
            }
            let author = commit.author();
            let author = match &mailmap {
                Some(mm) => mm.resolve_signature(&author).unwrap_or(author),
                None => author,
            };
            let name = bytes_to_string(author.name_bytes());
            let email = bytes_to_string(author.email_bytes());
            if let Some(re) = bot_regex {
                if re.is_match(&name) {
                    continue;
                }
            }
            total_commits += 1;
            *authors.entry((name, email)).or_insert(0) += 1;
            let t = commit.time().seconds();
            first_time = Some(first_time.map_or(t, |f: i64| f.min(t)));
            last_time = Some(last_time.map_or(t, |l: i64| l.max(t)));

            if churn_count < churn_limit {
                churn_count += 1;
                if commit.parent_count() <= 1 {
                    self.add_churn(&commit, &mut churn);
                }
            }
        }

        let mut authors: Vec<Author> = authors
            .into_iter()
            .map(|((name, email), commits)| Author {
                name,
                email,
                commits,
            })
            .collect();
        authors.sort_by(|a, b| {
            b.commits
                .cmp(&a.commits)
                .then_with(|| a.name.cmp(&b.name))
                .then_with(|| a.email.cmp(&b.email))
        });

        let mut churn: Vec<(String, usize)> = churn.into_iter().collect();
        churn.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

        Ok(CommitMetrics {
            authors,
            total_commits,
            first_commit_time: first_time.unwrap_or(0),
            last_commit_time: last_time.unwrap_or(0),
            churn,
            churn_pool_size: churn_count,
        })
    }

    fn add_churn(&self, commit: &git2::Commit, churn: &mut HashMap<String, usize>) {
        let tree = match commit.tree() {
            Ok(t) => t,
            Err(_) => return,
        };
        let parent_tree = commit.parent(0).ok().and_then(|p| p.tree().ok());
        let mut opts = DiffOptions::new();
        let diff = match self
            .repo
            .diff_tree_to_tree(parent_tree.as_ref(), Some(&tree), Some(&mut opts))
        {
            Ok(d) => d,
            Err(_) => return,
        };
        for delta in diff.deltas() {
            match delta.status() {
                Delta::Deleted => continue,
                _ => {}
            }
            let path = delta
                .new_file()
                .path()
                .or_else(|| delta.old_file().path());
            if let Some(p) = path {
                let s = p.to_string_lossy().to_string();
                *churn.entry(s).or_insert(0) += 1;
            }
        }
    }
}

