//! Minimal git URL parsing/normalization mimicking the behaviour observed in onefetch.

#[derive(Debug, Clone)]
pub struct GitUrl {
    pub scheme: Scheme,
    pub user: Option<String>,
    pub password: Option<String>,
    pub host: Option<String>,
    pub port: Option<u16>,
    pub path: String,
    /// scp-like form `user@host:path`
    pub scp_like: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Scheme {
    File,
    Git,
    Ssh,
    Http,
    Https,
    Ext(String),
}

impl Scheme {
    fn as_str(&self) -> &str {
        match self {
            Scheme::File => "file",
            Scheme::Git => "git",
            Scheme::Ssh => "ssh",
            Scheme::Http => "http",
            Scheme::Https => "https",
            Scheme::Ext(s) => s,
        }
    }
}

fn percent_encode_userinfo(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '@' | '/' | ':' | '?' | '#' | '[' | ']' | ' ' | '"' | '<' | '>' | '\\' | '^' | '`' | '{'
            | '|' | '}' => out.push_str(&format!("%{:02X}", c as u32)),
            _ => out.push(c),
        }
    }
    out
}

pub fn parse(input: &str) -> Result<GitUrl, String> {
    let input = input.trim();
    if input.is_empty() {
        return Err("URL is empty".into());
    }
    // scheme://...
    if let Some(idx) = input.find("://") {
        let scheme_raw = &input[..idx];
        if !scheme_raw.is_empty()
            && scheme_raw
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.')
        {
            let rest = &input[idx + 3..];
            let scheme_lower = scheme_raw.to_lowercase();
            let scheme = match scheme_lower.as_str() {
                "file" => Scheme::File,
                "git" => Scheme::Git,
                "ssh" | "git+ssh" | "ssh+git" => Scheme::Ssh,
                "http" => Scheme::Http,
                "https" => Scheme::Https,
                other => Scheme::Ext(other.to_string()),
            };
            if scheme == Scheme::File {
                return Ok(GitUrl {
                    scheme,
                    user: None,
                    password: None,
                    host: None,
                    port: None,
                    path: rest.to_string(),
                    scp_like: false,
                });
            }
            let (authority, path) = match rest.find('/') {
                Some(i) => (&rest[..i], &rest[i..]),
                None => (rest, ""),
            };
            let (userinfo, hostport) = match authority.rfind('@') {
                Some(i) => (Some(&authority[..i]), &authority[i + 1..]),
                None => (None, authority),
            };
            let (user, password) = match userinfo {
                Some(ui) => match ui.find(':') {
                    Some(i) => (Some(ui[..i].to_string()), Some(ui[i + 1..].to_string())),
                    None => (Some(ui.to_string()), None),
                },
                None => (None, None),
            };
            let (host, port) = match hostport.rfind(':') {
                Some(i) if hostport[i + 1..].chars().all(|c| c.is_ascii_digit()) && i + 1 < hostport.len() => {
                    let p: u16 = hostport[i + 1..]
