//! Line counting state machine modelled after tokei's behaviour.

use super::defs::{Context, Syntax};
use crate::langs::Language;
use std::collections::HashMap;

#[derive(Default, Debug, Clone)]
pub struct Stats {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
    pub blobs: HashMap<Language, Stats>,
}

impl Stats {
    /// Code including embedded blobs.
    pub fn total_code(&self) -> usize {
        self.code + self.blobs.values().map(|b| b.total_code()).sum::<usize>()
    }

    fn add_blob(&mut self, lang: Language, other: Stats) {
        let entry = self.blobs.entry(lang).or_default();
        entry.blanks += other.blanks;
        entry.code += other.code;
        entry.comments += other.comments;
        for (l, s) in other.blobs {
            entry.add_blob(l, s);
        }
    }
}

struct Counter<'a> {
    syntax: &'a Syntax,
    stack: Vec<&'static str>,
    quote: Option<&'static str>,
    quote_is_verbatim: bool,
    #[allow(dead_code)]
    quote_is_doc: bool,
}

fn trim_bytes(b: &[u8]) -> &[u8] {
    let mut s = 0;
    let mut e = b.len();
    while s < e && b[s].is_ascii_whitespace() {
        s += 1;
    }
    while e > s && b[e - 1].is_ascii_whitespace() {
        e -= 1;
    }
    &b[s..e]
}

fn trim_start_bytes(b: &[u8]) -> &[u8] {
    let mut s = 0;
    while s < b.len() && b[s].is_ascii_whitespace() {
        s += 1;
    }
    &b[s..]
}

fn trim_end_bytes(b: &[u8]) -> &[u8] {
    let mut e = b.len();
    while e > 0 && b[e - 1].is_ascii_whitespace() {
        e -= 1;
    }
    &b[..e]
}

enum Analysis {
    Normal(bool),
    Child {
        language: Language,
        block_start: usize,
        block_end: usize,
        resume: usize,
    },
}

impl<'a> Counter<'a> {
    fn new(syntax: &'a Syntax) -> Self {
        Counter {
            syntax,
            stack: Vec::new(),
            quote: None,
            quote_is_verbatim: false,
            quote_is_doc: false,
        }
    }

    fn is_plain_mode(&self) -> bool {
        self.stack.is_empty() && self.quote.is_none()
    }

    fn parse_end_of_quote(&mut self, window: &[u8]) -> Option<usize> {
        let quote = self.quote?;
        if window.starts_with(quote.as_bytes()) {
            self.quote = None;
            self.quote_is_doc = false;
            return Some(quote.len());
        }
        if !self.quote_is_verbatim && window.starts_with(b"\\") {
            return Some(2);
        }
        None
    }

    fn parse_end_of_multi_line(&mut self, window: &[u8]) -> Option<usize> {
        let last = *self.stack.last()?;
        if window.starts_with(last.as_bytes()) {
            self.stack.pop();
            return Some(last.len());
        }
        None
    }

    fn parse_quote(&mut self, window: &[u8]) -> Option<usize> {
        if !self.stack.is_empty() {
            return None;
        }
        for (start, end) in self.syntax.doc_quotes {
            if window.starts_with(start.as_bytes()) {
                self.quote = Some(end);
                self.quote_is_verbatim = false;
                self.quote_is_doc = true;
                return Some(start.len());
            }
        }
        for (start, end) in self.syntax.verbatim_quotes {
            if window.starts_with(start.as_bytes()) {
                self.quote = Some(end);
                self.quote_is_verbatim = true;
                self.quote_is_doc = false;
                return Some(start.len());
            }
        }
        for (start, end) in self.syntax.quotes {
            if window.starts_with(start.as_bytes()) {
                self.quote = Some(end);
                self.quote_is_verbatim = false;
                self.quote_is_doc = false;
                return Some(start.len());
            }
        }
        None
    }

    fn parse_multi_line_comment(&mut self, window: &[u8]) -> Option<usize> {
        if self.quote.is_some() {
            return None;
        }
        for &(start, end) in self.syntax.multi_line_comments {
            if window.starts_with(start.as_bytes()) {
                if self.stack.is_empty() || self.syntax.nested {
                    self.stack.push(end);
                }
                return Some(start.len());
            }
        }
        for &(start, end) in self.syntax.nested_comments {
            if window.starts_with(start.as_bytes()) {
                self.stack.push(end);
                return Some(start.len());
            }
        }
        None
    }

    fn parse_line_comment(&self, window: &[u8]) -> bool {
        if self.quote.is_some() || !self.stack.is_empty() {
            return false;
        }
        self.syntax
            .line_comments
            .iter()
            .any(|c| window.starts_with(c.as_bytes()))
    }

    fn try_single_line(&self, line: &[u8], stats: &mut Stats) -> bool {
        if !self.is_plain_mode() {
            return false;
        }
        let trimmed = trim_bytes(line);
        if trimmed.is_empty() {
            stats.blanks += 1;
            return true;
        }
        if self.syntax.has_important_syntax(line) {
            return false;
        }
        if self.syntax.literate
            || self
                .syntax
                .line_comments
                .iter()
                .any(|c| line.starts_with(c.as_bytes()))
        {
            stats.comments += 1;
        } else {
            stats.code += 1;
        }
        true
    }

    fn line_is_comment(&self, line: &[u8], ended_with_comments: bool, started_in_comments: bool) -> bool {
        let trimmed = trim_bytes(line);
        let whole_line_is_comment = || {
            self.syntax
                .line_comments
                .iter()
                .any(|c| trimmed.starts_with(c.as_bytes()))
                || self
                    .syntax
                    .multi_line_comments
                    .iter()
                    .chain(self.syntax.nested_comments.iter())
                    .any(|(s, e)| trimmed.starts_with(s.as_bytes()) && trimmed.ends_with(e.as_bytes()))
        };
        let starts_with_comment = || {
            let last = match self.stack.last() {
                Some(l) => *l,
                None => return false,
            };
            self.syntax
                .multi_line_comments
                .iter()
                .chain(self.syntax.nested_comments.iter())
                .any(|(s, e)| *e == last && trimmed.starts_with(s.as_bytes()))
        };
        if self.quote.is_some() {
            return false;
        }
        ((!self.stack.is_empty() || ended_with_comments) && started_in_comments)
            || whole_line_is_comment()
            || starts_with_comment()
    }

    /// Analyse one line; `lines` is the whole text, `start..end` the line range.
    fn perform_multi_line_analysis(&mut self, lines: &[u8], start: usize, end: usize) -> Analysis {
        let mut ended_with_comments = false;
        let mut skip = 0usize;
        let mut i = start;
        while i < end {
            if skip > 0 {
                skip -= 1;
                i += 1;
                continue;
            }
            let window = &lines[i..end];
            let full_window = &lines[i..];
            if let Some(n) = self
                .parse_end_of_quote(window)
                .or_else(|| self.parse_end_of_multi_line(window))
            {
                ended_with_comments = true;
                skip = n - 1;
                i += 1;
                continue;
            } else if self.quote.is_some() {
                i += 1;
                continue;
            }
            if self.stack.is_empty() {
                if let Some(child) = self.parse_context(lines, full_window, i, end) {
                    return child;
                }
            }
            if let Some(n) = self
                .parse_quote(window)
                .or_else(|| self.parse_multi_line_comment(window))
            {
                ended_with_comments = false;
                skip = n - 1;
                i += 1;
                continue;
            }
            if self.parse_line_comment(window) {
                ended_with_comments = true;
                break;
            }
            i += 1;
        }
        Analysis::Normal(ended_with_comments)
    }

    fn parse_context(&self, lines: &[u8], window: &[u8], pos: usize, line_end: usize) -> Option<Analysis> {
        match self.syntax.context {
            Context::None => None,
            Context::Markdown => {
                if !window.starts_with(b"```") {
                    return None;
                }
                let info = trim_end_bytes(&lines[pos + 3..line_end]);
                let info = std::str::from_utf8(info).ok()?;
                if info.chars().any(|c| c.is_whitespace()) {
                    return None;
                }
                let language = info
                    .split(',')
                    .find_map(|p| Language::from_display_name_ci(p))?;
                // block starts after this line
                let block_start = if line_end < lines.len() { line_end + 1 } else { lines.len() };
                let rest = &lines[block_start..];
                let (block_end, resume) = match find(rest, b"```") {
                    None => (lines.len(), lines.len()),
                    Some(idx) => {
                        let abs = block_start + idx;
                        // must be at start of line (after whitespace) and followed by whitespace to EOL
                        let line_start = lines[..abs]
                            .iter()
                            .rposition(|&b| b == b'\n')
                            .map(|p| p + 1)
                            .unwrap_or(0);
                        if !trim_bytes(&lines[line_start..abs]).is_empty() {
                            return None;
                        }
                        let after = &lines[abs + 3..];
                        let eol = after.iter().position(|&b| b == b'\n').unwrap_or(after.len());
                        if !trim_bytes(&after[..eol]).is_empty() {
                            return None;
                        }
                        (line_start, line_start)
                    }
                };
                Some(Analysis::Child {
                    language,
                    block_start,
                    block_end,
                    resume,
                })
            }
            Context::Html => {
                let (tag, default_lang, close): (&[u8], Language, &[u8]) = if window.starts_with(b"<script") {
                    (b"<script", Language::from_name("JavaScript")?, b"</script>")
                } else if window.starts_with(b"<style") {
                    (b"<style", Language::from_name("Css")?, b"</style>")
                } else {
                    return None;
                };
                // the tag must end with '>' on this line and be followed only by whitespace
                let tag_rest = &lines[pos + tag.len()..line_end];
                let gt = tag_rest.iter().position(|&b| b == b'>')?;
                let attrs = &tag_rest[..gt];
                if !attrs.is_empty() && !(attrs[0].is_ascii_whitespace()) {
                    return None;
                }
                if !trim_bytes(&tag_rest[gt + 1..]).is_empty() {
                    return None;
                }
                let attrs = String::from_utf8_lossy(attrs).to_string();
                let mut language = default_lang;
                if let Some(l) = attr_value(&attrs, "lang") {
                    if let Some(lang) = Language::from_display_name_ci(&l).or_else(|| super::defs::from_extension(&l)) {
                        language = lang;
                    }
                } else if let Some(t) = attr_value(&attrs, "type") {
                    let t = t.trim().to_lowercase();
                    let t = t
                        .trim_start_matches("text/")
                        .trim_start_matches("application/");
                    if let Some(lang) = match t {
                        "javascript" | "module" | "ecmascript" | "x-javascript" => Language::from_name("JavaScript"),
                        "typescript" | "x-typescript" => Language::from_name("TypeScript"),
                        "json" | "ld+json" | "importmap" => Language::from_name("Json"),
                        "css" => Language::from_name("Css"),
                        _ => None,
                    } {
                        language = lang;
                    }
                }
                let block_start = if line_end < lines.len() { line_end + 1 } else { lines.len() };
                let rest = &lines[block_start..];
                let (block_end, resume) = match find(rest, close) {
                    None => (lines.len(), lines.len()),
                    Some(idx) => (block_start + idx, block_start + idx),
                };
                Some(Analysis::Child {
                    language,
                    block_start,
                    block_end,
                    resume,
                })
            }
        }
    }
}

fn attr_value(attrs: &str, name: &str) -> Option<String> {
    let mut search = 0;
    while let Some(i) = attrs[search..].find(name) {
        let abs = search + i;
        let before_ok = abs == 0 || !attrs.as_bytes()[abs - 1].is_ascii_alphanumeric();
        let after = &attrs[abs + name.len()..];
        let after_t = after.trim_start();
        if before_ok && after_t.starts_with('=') {
            let v = after_t[1..].trim_start();
