                if q == '"' || q == '\'' {
                    let inner = &v[1..];
                    if let Some(e) = inner.find(q) {
                        return Some(inner[..e].to_string());
                    }
                    return None;
                }
                let e = v.find(|c: char| c.is_whitespace()).unwrap_or(v.len());
                return Some(v[..e].to_string());
            }
        }
        search = abs + name.len();
    }
    None
}

