pub mod defs;
pub mod engine;

use std::collections::HashMap;
use std::path::Path;

use crate::config::LanguageType;
use crate::langs::Language;

/// Walk the directory and compute lines of code per language.
pub fn get_statistics(
    root: &Path,
    excludes: &[String],
    include_hidden: bool,
) -> HashMap<Language, usize> {
    let mut builder = ignore::WalkBuilder::new(root);
    builder
        .hidden(!include_hidden)
        .git_ignore(true)
        .git_exclude(true)
        .git_global(true)
        .ignore(true)
        .parents(true)
        .follow_links(false);
    builder.add_custom_ignore_filename(".tokeignore");
    let mut overrides = ignore::overrides::OverrideBuilder::new(root);
    for pat in excludes {
        let _ = overrides.add(&format!("!{}", pat));
    }
    if let Ok(ov) = overrides.build() {
        builder.overrides(ov);
    }

    let mut result: HashMap<Language, usize> = HashMap::new();
    for entry in builder.build().flatten() {
        let is_file = entry
            .file_type()
            .map(|t| t.is_file())
            .unwrap_or(false);
        if !is_file {
            continue;
        }
        let path = entry.path();
        let lang = match defs::language_from_path(path) {
            Some(l) => l,
            None => continue,
        };
        let data = match std::fs::read(path) {
            Ok(d) => d,
            Err(_) => continue,
        };
        let stats = if lang.name() == "Jupyter" {
            parse_jupyter(&data)
        } else {
            engine::parse(lang, &data)
        };
        *result.entry(lang).or_insert(0) += stats.total_code();
    }
    result
}

pub fn filter_by_type(stats: &HashMap<Language, usize>, types: &[LanguageType]) -> Vec<(Language, usize)> {
    let mut v: Vec<(Language, usize)> = stats
        .iter()
        .filter(|(l, c)| **c > 0 && types.contains(&l.kind()))
        .map(|(l, c)| (*l, *c))
        .collect();
    v.sort_by(|a, b| b.1.cmp(&a.1));
    v
}

fn parse_jupyter(data: &[u8]) -> engine::Stats {
    let mut stats = engine::Stats::default();
