    };
    if !meta.contains_key("kernelspec") {
        return stats;
    }
    let lang_name = match meta
        .get("language_info")
        .and_then(|l| l.as_object())
        .and_then(|l| l.get("name"))
        .and_then(|n| n.as_str())
    {
        Some(n) => n,
        None => return stats,
    };
    let language = Language::from_display_name_ci(lang_name)
        .unwrap_or_else(|| Language::from_name("Python").unwrap());
    let markdown = Language::from_name("Markdown").unwrap();
    let cells = match obj.get("cells").and_then(|c| c.as_array()) {
        Some(c) => c,
        None => return stats,
    };
    for cell in cells {
