        if !cfg.input.is_dir() {
            anyhow::bail!(
                "Failed to access a directory, or path is not a directory: '{}'",
                cfg.input_display
            );
        }
        let repo = Repo::open(&cfg.input, &cfg.input_display)?;
        let workdir = repo.workdir.clone();

        // ensure HEAD is valid early (errors like unborn branch)
        let (short_id, refs) = repo.head_refs()?;

        let bot_regex = match &cfg.no_bots {
