                        .context("The fetch url under `remote.origin` was invalid")
                        .context(format!(
                            "The url at \"remote.<name>.url={}\" could not be parsed",
                            raw
                        ))
                        .context(e)
                })?;
                let mut name = parsed.repo_name();
                if name.is_empty() {
                    if let Some(m) = &manifest {
                        name = m.name.clone();
                    }
                }
                let mut url = parsed.to_display(cfg.hide_token);
                if cfg.http_url {
                    url = to_http_url(&url);
                }
                (name, url)
            }
        };

        // Languages
        let stats = crate::tokei::get_statistics(&workdir, &cfg.exclude, cfg.include_hidden);
        let types: Vec<LanguageType> = cfg.types.clone();
        let languages = crate::tokei::filter_by_type(&stats, &types);
        let total_loc: usize = languages.iter().map(|(_, c)| c).sum();
        let dominant_language = languages
            .first()
            .map(|(l, _)| *l)
            .unwrap_or(Language::UNKNOWN);

        let license = crate::license::Detector::new().get_license(&workdir);

        let (size_bytes, file_count) = repo.size();
        let (added, deleted, modified) = repo.pending();

        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        let fmt_time = |t: i64| -> String {
            if cfg.iso_time {
                crate::humantime::iso8601_utc(t)
            } else {
                crate::humantime::humanize(now - t)
            }
        };

        let version = match repo.version_from_tags() {
