            None => manifest.as_ref().map(|m| m.version.clone()).unwrap_or_default(),
        };
        let description = manifest.as_ref().and_then(|m| m.description.clone());
        let dependencies = match &manifest {
            Some(m) if m.number_of_dependencies > 0 => {
                format!("{} ({})", m.number_of_dependencies, m.manifest_type.as_str())
            }
            _ => String::new(),
        };
        let license = if let Some(m) = &manifest {
            match &m.license {
                Some(l) if !l.is_empty() => l.clone(),
                _ => license,
            }
        } else {
            license
        };

        let total_authors = metrics.authors.len();
        let authors: Vec<AuthorOut> = metrics
            .authors
            .iter()
            .take(cfg.number_of_authors)
            .map(|a| AuthorOut {
                name: a.name.clone(),
                email: if cfg.email { Some(a.email.clone()) } else { None },
                nbr_of_commits: a.commits,
                contribution: percentage_round(a.commits, metrics.total_commits),
            })
            .collect();

        let churns: Vec<FileChurn> = metrics
            .churn
            .iter()
            .take(cfg.number_of_file_churns)
            .map(|(p, c)| FileChurn {
                file_path: p.clone(),
                nbr_of_commits: *c,
            })
            .collect();

        let mut fields: Vec<InfoField> = Vec::new();
        let push = |fields: &mut Vec<InfoField>, key: &str, f: InfoField| {
            if !cfg.is_disabled(key) {
                fields.push(f);
            }
        };
