pub mod ascii;

use anyhow::Result;

use crate::config::{Config, NumberSeparator, TrueColor};
use crate::info::{Info, InfoField};
use crate::langs::Language;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Ansi(u8),
    Rgb(u8, u8, u8),
}

pub const DEFAULT: Color = Color::Ansi(39);
pub const WHITE: Color = Color::Ansi(37);

impl Color {
    pub fn fg(&self) -> String {
        match self {
            Color::Ansi(c) => c.to_string(),
            Color::Rgb(r, g, b) => format!("38;2;{};{};{}", r, g, b),
        }
    }
    pub fn bg(&self) -> String {
        match self {
            Color::Ansi(c) => (c + 10).to_string(),
            Color::Rgb(r, g, b) => format!("48;2;{};{};{}", r, g, b),
        }
    }
    pub fn from_index(i: u8) -> Color {
        if i < 8 {
            Color::Ansi(30 + i)
        } else {
            Color::Ansi(90 + (i - 8))
        }
    }
}

/// owo-colors style: `ESC[<fg>[;1]m text ESC[0m`
pub fn style(text: &str, color: Color, bold: bool) -> String {
    if bold {
        format!("\x1b[{};1m{}\x1b[0m", color.fg(), text)
    } else {
        format!("\x1b[{}m{}\x1b[0m", color.fg(), text)
    }
}

/// owo-colors `.color()`: `ESC[<fg>m text ESC[39m`
pub fn colored(text: &str, color: Color) -> String {
    format!("\x1b[{}m{}\x1b[39m", color.fg(), text)
}

pub fn on_color(text: &str, color: Color) -> String {
    format!("\x1b[{}m{}\x1b[49m", color.bg(), text)
}

pub struct TextColors {
    pub title: Color,
    pub tilde: Color,
    pub underline: Color,
    pub subtitle: Color,
    pub colon: Color,
    pub info: Color,
}

impl TextColors {
    pub fn new(overrides: &[u8], base: Color) -> TextColors {
        let mut tc = TextColors {
            title: base,
            tilde: DEFAULT,
            underline: DEFAULT,
            subtitle: base,
            colon: DEFAULT,
            info: DEFAULT,
        };
        let get = |i: usize| overrides.get(i).map(|v| Color::from_index(*v));
        if let Some(c) = get(0) {
            tc.title = c;
        }
        if let Some(c) = get(1) {
            tc.tilde = c;
        }
        if let Some(c) = get(2) {
            tc.underline = c;
        }
        if let Some(c) = get(3) {
            tc.subtitle = c;
        }
        if let Some(c) = get(4) {
            tc.colon = c;
        }
        if let Some(c) = get(5) {
            tc.info = c;
        }
        tc
    }
}

pub fn use_true_color(cfg: &Config) -> bool {
    match cfg.true_color {
        TrueColor::Always => true,
        TrueColor::Never => false,
        TrueColor::Auto => match std::env::var("COLORTERM") {
            Ok(v) => {
                let v = v.to_lowercase();
                v == "truecolor" || v == "24bit"
            }
            Err(_) => false,
        },
    }
}

/// Colors for the ascii art: overrides, then language colors, then default.
pub fn ascii_colors(lang: Language, overrides: &[u8], true_color: bool) -> Vec<Color> {
    let lang_colors: Vec<Color> = if true_color && !lang.true_colors().is_empty() {
        lang.true_colors()
            .iter()
            .map(|(r, g, b)| Color::Rgb(*r, *g, *b))
            .collect()
    } else {
        lang.basic_colors().iter().map(|c| Color::Ansi(*c)).collect()
    };
    let n = overrides.len().max(lang_colors.len());
    (0..n)
        .map(|i| {
            overrides
                .get(i)
                .map(|v| Color::from_index(*v))
                .unwrap_or_else(|| lang_colors.get(i).copied().unwrap_or(DEFAULT))
        })
        .collect()
}

pub fn format_number(n: usize, sep: NumberSeparator) -> String {
    let s = n.to_string();
    let sep_str = match sep {
        NumberSeparator::Plain => return s,
        NumberSeparator::Comma => ",",
        NumberSeparator::Space => "\u{202f}",
        NumberSeparator::Underscore => "_",
    };
    let bytes: Vec<char> = s.chars().collect();
    let mut out = String::new();
    for (i, c) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            out.push_str(sep_str);
        }
        out.push(*c);
    }
    out
}

struct RenderCtx<'a> {
    info: &'a Info,
    cfg: &'a Config,
    true_color: bool,
    text_colors: TextColors,
    bold: bool,
}

fn chip_color(idx: usize, lang: Language, true_color: bool) -> Color {
    if true_color {
        if let Some((r, g, b)) = lang.chip() {
            return Color::Rgb(r, g, b);
        }
    }
    const PALETTE: [u8; 6] = [31, 32, 33, 34, 35, 36];
    Color::Ansi(PALETTE[idx % PALETTE.len()])
}

impl<'a> RenderCtx<'a> {
    fn field_value(&self, field: &InfoField) -> Option<(String, String)> {
        let sep = self.cfg.number_separator;
        match field {
            InfoField::ProjectInfo {
                repo_name,
                number_of_branches,
                number_of_tags,
            } => {
                if repo_name.is_empty() {
                    return None;
                }
                let mut parts = Vec::new();
                if *number_of_branches > 0 {
                    parts.push(format!(
                        "{} {}",
                        format_number(*number_of_branches, sep),
                        if *number_of_branches == 1 { "branch" } else { "branches" }
                    ));
                }
                if *number_of_tags > 0 {
                    parts.push(format!(
                        "{} {}",
                        format_number(*number_of_tags, sep),
                        if *number_of_tags == 1 { "tag" } else { "tags" }
                    ));
                }
                let value = if parts.is_empty() {
                    repo_name.clone()
                } else {
                    format!("{} ({})", repo_name, parts.join(", "))
                };
                Some(("Project".to_string(), value))
            }
            InfoField::DescriptionInfo { description } => {
                let d = description.as_ref()?;
                let words: Vec<&str> = d.split_whitespace().collect();
                if words.is_empty() {
                    return None;
                }
                let lines: Vec<String> = words.chunks(5).map(|c| c.join(" ")).collect();
                Some(("Description".to_string(), lines.join("\n")))
            }
            InfoField::HeadInfo { head_refs } => {
                let value = if head_refs.refs.is_empty() {
                    head_refs.short_commit_id.clone()
                } else {
                    format!("{} ({})", head_refs.short_commit_id, head_refs.refs.join(", "))
                };
                Some(("HEAD".to_string(), value))
            }
            InfoField::PendingInfo {
                added,
                deleted,
                modified,
            } => {
                let mut parts = Vec::new();
                if *modified > 0 {
                    parts.push(format!("{}+-", modified));
                }
                if *added > 0 {
                    parts.push(format!("{}+", added));
                }
                if *deleted > 0 {
                    parts.push(format!("{}-", deleted));
                }
                if parts.is_empty() {
                    return None;
                }
                Some(("Pending".to_string(), parts.join(" ")))
            }
            InfoField::VersionInfo { version } => {
                if version.is_empty() {
                    return None;
                }
                Some(("Version".to_string(), version.clone()))
            }
            InfoField::CreatedInfo { creation_date } => Some(("Created".to_string(), creation_date.clone())),
            InfoField::LanguagesInfo { languages_with_percentage } => {
                let langs = &self.info.languages;
                if langs.is_empty() {
                    return None;
                }
                let title = if languages_with_percentage.len() > 1 { "Languages" } else { "Language" };
                let pad = " ".repeat(title.len() + 2);
                // (name, percentage, color)
                let mut items: Vec<(String, f64, Color)> = Vec::new();
                let n = self.cfg.number_of_languages;
                let total: usize = langs.iter().map(|(_, c)| c).sum();
                let mut other = 0.0f64;
                for (i, (lang, count)) in langs.iter().enumerate() {
                    let pct = *count as f64 / total as f64 * 100.0;
                    if i < n {
                        items.push((lang.display_name().to_string(), pct, chip_color(i, *lang, self.true_color)));
                    } else {
                        other += pct;
                    }
                }
                if langs.len() > n {
                    items.push(("Other".to_string(), other, WHITE));
                }
                // bar
                let mut bar = String::new();
                for (_, pct, color) in &items {
                    let width = ((pct / 100.0 * 26.0).round() as usize).max(1);
                    bar.push_str(&on_color(&" ".repeat(width), *color));
                }
                let mut value = bar;
                value.push('\n');
                let bullet = |lang_name: &str| -> String {
                    if self.cfg.nerd_fonts {
                        langs
                            .iter()
                            .find(|(l, _)| l.display_name() == lang_name)
                            .map(|(l, _)| l.icon().to_string())
                            .unwrap_or_else(|| "\u{25cf}".to_string())
                    } else {
                        "\u{25cf}".to_string()
                    }
                };
                let count = items.len();
                let mut body = String::new();
                for (i, (name, pct, color)) in items.iter().enumerate() {
                    let b = bullet(name);
                    body.push_str(&format!(
                        "{} {}",
                        colored(&b, *color),
                        colored(&format!("{} ({:.1} %)", name, pct), self.text_colors.info)
                    ));
                    if i % 2 == 0 {
                        body.push(' ');
                    } else if i + 1 < count {
                        body.push('\n');
                        body.push_str(&pad);
                    }
                }
                // body lines already include pad for continuation lines; the first body line
                // needs pad too (added by the caller for continuation lines)
                value.push_str(&body);
                Some((title.to_string(), value))
            }
            InfoField::DependenciesInfo { dependencies } => {
                if dependencies.is_empty() {
                    return None;
                }
                Some(("Dependencies".to_string(), dependencies.clone()))
            }
            InfoField::AuthorsInfo { authors } => {
                if authors.is_empty() {
                    return None;
                }
                let title = if authors.len() > 1 { "Authors" } else { "Author" };
                let lines: Vec<String> = authors
                    .iter()
                    .map(|a| {
                        let mut s = format!("{}% {}", a.contribution, a.name);
                        if let Some(e) = &a.email {
