                    })
                    .collect();
                Some((title.to_string(), lines.join("\n")))
            }
            InfoField::LastChangeInfo { last_change } => Some(("Last change".to_string(), last_change.clone())),
            InfoField::ContributorsInfo { total_number_of_authors } => {
