                    return None;
                }
                Some(("License".to_string(), license.clone()))
            }
        }
    }

    fn info_lines(&self) -> Vec<String> {
        let mut lines = Vec::new();
        let tc = &self.text_colors;
        if !self.cfg.no_title {
            let user = &self.info.title.git_username;
            let version = &self.info.title.git_version;
            let mut title = String::new();
            let mut len = 0usize;
            title.push_str(&style(user, tc.title, self.bold));
            len += user.chars().count();
            if !user.is_empty() && !version.is_empty() {
                title.push(' ');
                title.push_str(&style("~", tc.tilde, self.bold));
                title.push(' ');
                len += 3;
            }
            title.push_str(&style(version, tc.title, self.bold));
            len += version.chars().count();
            lines.push(title);
            lines.push(colored(&"-".repeat(len), tc.underline));
        }
        for field in &self.info.fields {
            if let Some((subtitle, value)) = self.field_value(field) {
                let pad = " ".repeat(subtitle.chars().count() + 2);
                for (i, vline) in value.split('\n').enumerate() {
                    if i == 0 {
                        lines.push(format!(
                            "{}{} {}",
                            style(&subtitle, tc.subtitle, self.bold),
                            style(":", tc.colon, self.bold),
                            style(vline, tc.info, false)
                        ));
                    } else {
                        // continuation lines: for languages, the pad is already included
                        // for lines after the second one; normalise by stripping and re-adding
                        let content = if vline.starts_with(&pad) { &vline[pad.len()..] } else { vline };
                        lines.push(style(&format!("{}{}", pad, content), tc.info, false));
                    }
                }
            }
        }
        if !self.cfg.no_color_palette {
            lines.push(String::new());
            let mut palette = String::new();
            for i in 0..8u8 {
                palette.push_str(&on_color("   ", Color::Ansi(30 + i)));
            }
            lines.push(palette);
        }
        lines
    }
}

pub fn render(info: &Info, cfg: &Config) -> Result<String> {
    let true_color = use_true_color(cfg);
    let dominant = info.dominant_language;
    let art_language = if dominant.is_unknown() {
        dominant
    } else {
        cfg.ascii_language.unwrap_or(dominant)
    };
    let colors = ascii_colors(art_language, &cfg.ascii_colors, true_color);
    let base = colors.first().copied().unwrap_or(WHITE);
    let text_colors = TextColors::new(&cfg.text_colors, base);
    let ctx = RenderCtx {
        info,
        cfg,
        true_color,
        text_colors,
        bold: !cfg.no_bold,
    };

    // image handling (errors when not a tty)
    if let Some(img) = &cfg.image {
        crate::ui::ascii::check_image(img, cfg)?;
    }

    let info_lines = ctx.info_lines();

    let art_lines: Vec<String> = if cfg.no_art || cfg.image.is_some() {
        Vec::new()
    } else if let Some(input) = &cfg.ascii_input {
        if input.is_empty() {
            ascii::panic_empty_input();
        }
        ascii::render_art(input, &colors, !cfg.no_bold)
    } else if art_language.is_unknown() {
        Vec::new()
    } else {
        ascii::render_art(art_language.ascii(), &colors, !cfg.no_bold)
    };

    let mut out = String::new();
    out.push_str("\x1b[?7l");
    if art_lines.is_empty() {
        for l in &info_lines {
            out.push_str(l);
            out.push('\n');
        }
    } else {
        let width = ascii::art_width(&art_lines);
        let n = art_lines.len().max(info_lines.len());
        for i in 0..n {
            match (art_lines.get(i), info_lines.get(i)) {
                (Some(a), Some(l)) => {
                    out.push_str(a);
                    out.push_str("   ");
                    out.push_str(l);
                }
                (Some(a), None) => {
                    out.push_str(a);
                }
                (None, Some(l)) => {
                    out.push_str(&" ".repeat(width + 3));
                    out.push_str(l);
                }
                (None, None) => {}
            }
            out.push('\n');
        }
    }
    out.push_str("\x1b[?7h");
    Ok(out)
}
