pub mod ascii;

use anyhow::Result;

use crate::config::{Config, NumberSeparator, TrueColor};
use crate::info::{Info, InfoField};
use crate::langs::Language;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Ansi(u8),
    Rgb(u8, u8, u8),
}

pub const DEFAULT: Color = Color::Ansi(39);
pub const WHITE: Color = Color::Ansi(37);

impl Color {
    pub fn fg(&self) -> String {
        match self {
            Color::Ansi(c) => c.to_string(),
            Color::Rgb(r, g, b) => format!("38;2;{};{};{}", r, g, b),
        }
    }
    pub fn bg(&self) -> String {
        match self {
            Color::Ansi(c) => (c + 10).to_string(),
            Color::Rgb(r, g, b) => format!("48;2;{};{};{}", r, g, b),
        }
    }
    pub fn from_index(i: u8) -> Color {
        if i < 8 {
            Color::Ansi(30 + i)
        } else {
            Color::Ansi(90 + (i - 8))
        }
    }
}

/// owo-colors style: `ESC[<fg>[;1]m text ESC[0m`
pub fn style(text: &str, color: Color, bold: bool) -> String {
    if bold {
        format!("\x1b[{};1m{}\x1b[0m", color.fg(), text)
    } else {
        format!("\x1b[{}m{}\x1b[0m", color.fg(), text)
    }
}

/// owo-colors `.color()`: `ESC[<fg>m text ESC[39m`
pub fn colored(text: &str, color: Color) -> String {
    format!("\x1b[{}m{}\x1b[39m", color.fg(), text)
}

pub fn on_color(text: &str, color: Color) -> String {
    format!("\x1b[{}m{}\x1b[49m", color.bg(), text)
}

pub struct TextColors {
    pub title: Color,
    pub tilde: Color,
    pub underline: Color,
    pub subtitle: Color,
    pub colon: Color,
    pub info: Color,
}

impl TextColors {
    pub fn new(overrides: &[u8], base: Color) -> TextColors {
        let mut tc = TextColors {
            title: base,
            tilde: DEFAULT,
            underline: DEFAULT,
            subtitle: base,
            colon: DEFAULT,
            info: DEFAULT,
        };
        let get = |i: usize| overrides.get(i).map(|v| Color::from_index(*v));
        if let Some(c) = get(0) {
            tc.title = c;
        }
        if let Some(c) = get(1) {
            tc.tilde = c;
        }
        if let Some(c) = get(2) {
            tc.underline = c;
        }
        if let Some(c) = get(3) {
            tc.subtitle = c;
        }
        if let Some(c) = get(4) {
            tc.colon = c;
        }
        if let Some(c) = get(5) {
            tc.info = c;
        }
        tc
    }
}

pub fn use_true_color(cfg: &Config) -> bool {
    match cfg.true_color {
        TrueColor::Always => true,
        TrueColor::Never => false,
        TrueColor::Auto => match std::env::var("COLORTERM") {
            Ok(v) => {
                let v = v.to_lowercase();
                v == "truecolor" || v == "24bit"
            }
            Err(_) => false,
        },
    }
}

/// Colors for the ascii art: overrides, then language colors, then default.
pub fn ascii_colors(lang: Language, overrides: &[u8], true_color: bool) -> Vec<Color> {
    let lang_colors: Vec<Color> = if true_color && !lang.true_colors().is_empty() {
        lang.true_colors()
            .iter()
            .map(|(r, g, b)| Color::Rgb(*r, *g, *b))
            .collect()
    } else {
        lang.basic_colors().iter().map(|c| Color::Ansi(*c)).collect()
    };
    let n = overrides.len().max(lang_colors.len());
    (0..n)
        .map(|i| {
            overrides
                .get(i)
                .map(|v| Color::from_index(*v))
                .unwrap_or_else(|| lang_colors.get(i).copied().unwrap_or(DEFAULT))
        })
        .collect()
}

pub fn format_number(n: usize, sep: NumberSeparator) -> String {
    let s = n.to_string();
    let sep_str = match sep {
        NumberSeparator::Plain => return s,
        NumberSeparator::Comma => ",",
        NumberSeparator::Space => "\u{202f}",
        NumberSeparator::Underscore => "_",
    };
    let bytes: Vec<char> = s.chars().collect();
    let mut out = String::new();
    for (i, c) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            out.push_str(sep_str);
        }
        out.push(*c);
    }
    out
}

struct RenderCtx<'a> {
    info: &'a Info,
    cfg: &'a Config,
    true_color: bool,
    text_colors: TextColors,
    bold: bool,
}

fn chip_color(idx: usize, lang: Language, true_color: bool) -> Color {
    if true_color {
        if let Some((r, g, b)) = lang.chip() {
            return Color::Rgb(r, g, b);
        }
    }
    const PALETTE: [u8; 6] = [31, 32, 33, 34, 35, 36];
    Color::Ansi(PALETTE[idx % PALETTE.len()])
}

