//! Minimal local implementation of terminal size detection via ioctl.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

fn size_of_fd(fd: i32) -> Option<(Width, Height)> {
    unsafe {
        if isatty(fd) != 1 {
            return None;
        }
        let mut ws = WinSize::default();
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == -1 {
            return None;
        }
        if ws.ws_col == 0 || ws.ws_row == 0 {
            return None;
        }
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    }
}

/// Returns the size of the terminal, if available (checks stdout, then stderr, then stdin).
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(1).or_else(|| size_of_fd(2)).or_else(|| size_of_fd(0))
}

pub fn terminal_size_of<F: std::os::fd::AsFd>(fd: F) -> Option<(Width, Height)> {
    use std::os::fd::AsRawFd;
    size_of_fd(fd.as_fd().as_raw_fd())
}
