    repo: &'a Repository,
    heap: std::collections::BinaryHeap<(i64, std::cmp::Reverse<usize>, OidKey)>,
    seen: std::collections::HashSet<Oid>,
    counter: usize,
}

#[derive(PartialEq, Eq, PartialOrd, Ord)]
struct OidKey([u8; 20]);

impl<'a> TimeWalk<'a> {
    fn new(repo: &'a Repository, tip: Oid) -> Self {
        let mut w = TimeWalk {
